const now = new Date();
const untilIso = now.toISOString();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceIso = since.toISOString();
const sinceDate = sinceIso.slice(0, 10);
const untilDate = untilIso.slice(0, 10);

const owner = $vars.github_owner;
const repo = $vars.github_repo;
const language = String($vars.summary_language || 'EN').toUpperCase();
const anthropicApiKey = $vars.anthropic_api_key;
const destinationWebhookUrl = $vars.destination_webhook_url;
const githubToken = $vars.github_token;

const missing = [];
for (const [name, value] of Object.entries({ github_owner: owner, github_repo: repo, summary_language: language, anthropic_api_key: anthropicApiKey, destination_webhook_url: destinationWebhookUrl })) {
  if (!value) missing.push(name);
}
if (missing.length) {
  throw new Error(`Missing n8n variable(s): ${missing.join(', ')}`);
}
if (!['EN', 'FR'].includes(language)) {
  throw new Error('summary_language must be EN or FR');
}

const githubHeaders = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'weekly-dev-summary-n8n'
};
if (githubToken) {
  githubHeaders.Authorization = `Bearer ${githubToken}`;
}

return [{
  json: {
    owner,
    repo,
    language,
    sinceIso,
    untilIso,
    sinceDate,
    untilDate,
    githubHeaders,
    anthropicApiKey,
    destinationWebhookUrl,
    repoLabel: `${owner}/${repo}`
  }
}];

const config = $items('Build config')[0].json;
const windowStart = new Date(config.sinceIso).getTime();
const windowEnd = new Date(config.untilIso).getTime();

function collectRows(nodeName) {
  const rows = $items(nodeName).map((item) => item.json);
  if (rows.length === 1 && Array.isArray(rows[0])) return rows[0];
  if (rows.length === 1 && Array.isArray(rows[0].items)) return rows[0].items;
  return rows;
}

function firstLine(value) {
  return String(value || '').split('\n')[0];
}

function inWindow(value) {
  const timestamp = new Date(value || 0).getTime();
  return timestamp >= windowStart && timestamp <= windowEnd;
}

const commits = collectRows('Fetch commits')
  .filter((commit) => commit.sha || commit.commit)
  .map((commit) => ({
    sha: String(commit.sha || '').slice(0, 7),
    message: firstLine(commit.commit?.message),
    author: commit.commit?.author?.name || commit.author?.login || 'unknown',
    url: commit.html_url
  }));

const closedIssues = collectRows('Fetch closed issues')
  .filter((issue) => issue.number && !issue.pull_request && inWindow(issue.closed_at))
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    closedAt: issue.closed_at,
    url: issue.html_url
  }));

const mergedPullRequests = collectRows('Fetch merged pull requests')
  .filter((pullRequest) => pullRequest.number && pullRequest.merged_at && inWindow(pullRequest.merged_at))
  .map((pullRequest) => ({
    number: pullRequest.number,
    title: pullRequest.title,
    mergedAt: pullRequest.merged_at,
    author: pullRequest.user?.login,
    url: pullRequest.html_url
  }));

const activity = {
  repository: config.repoLabel,
  window: {
    since: config.sinceIso,
    until: config.untilIso
  },
  counts: {
    commits: commits.length,
    closedIssues: closedIssues.length,
    mergedPullRequests: mergedPullRequests.length
  },
  commits,
  closedIssues,
  mergedPullRequests
};

const languageName = config.language === 'FR' ? 'French' : 'English';
const prompt = `Write a weekly development summary in ${languageName} for ${config.repoLabel}.

Use a narrative style suitable for posting to a team channel. Include:
- a short opening paragraph,
- highlights from commits,
- closed issues,
- merged pull requests,
- useful follow-ups for next week.

Keep it concise and factual. Do not invent work that is not present in the JSON.

GitHub activity JSON:
${JSON.stringify(activity, null, 2)}`;

return [{
  json: {
    ...config,
    activity,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      temperature: 0.2,
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const config = $items('Build config')[0].json;
const activity = $items('Compose Claude request')[0].json.activity;
const textBlock = Array.isArray($json.content) ? $json.content.find((block) => block.type === 'text') : null;
const summary = textBlock?.text || $json.text || JSON.stringify($json);

const slackPayload = {
  text: `Weekly dev summary for ${config.repoLabel}`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `Weekly dev summary: ${config.repoLabel}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: summary.slice(0, 2900)
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `${config.sinceDate} to ${config.untilDate} | ${activity.counts.commits} commits | ${activity.counts.closedIssues} closed issues | ${activity.counts.mergedPullRequests} merged PRs`
        }
      ]
    }
  ]
};

return [{
  json: {
    webhookUrl: config.destinationWebhookUrl,
    summary,
    slackPayload
  }
}];
